typedef enum { BROTLI_PARAM_QUALITY = 1, BROTLI_PARAM_LGWIN = 2, BROTLI_PARAM_LARGE_WINDOW = 6 } BrotliEncoderParameter;
typedef enum { BROTLI_OPERATION_PROCESS = 0, BROTLI_OPERATION_FINISH = 2, BROTLI_OPERATION_EMIT_METADATA = 3 } BrotliEncoderOperation;
typedef enum { BROTLI_DECODER_RESULT_ERROR = 0, BROTLI_DECODER_RESULT_SUCCESS = 1, BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT = 2, BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT = 3 } BrotliDecoderResult;

extern BrotliEncoderState BrotliEncoderCreateInstance(void* a, void* b, void* c);
extern bool BrotliEncoderSetParameter(BrotliEncoderState state, BrotliEncoderParameter param, uint32_t value);
extern bool BrotliEncoderCompressStream(BrotliEncoderState state, BrotliEncoderOperation op, size_t* avail_in, const uint8_t** next_in, size_t* avail_out, uint8_t** next_out, size_t* total_out);
extern bool BrotliEncoderIsFinished(BrotliEncoderState state);
extern void BrotliEncoderDestroyInstance(BrotliEncoderState state);
extern BrotliDecoderState BrotliDecoderCreateInstance(void* a, void* b, void* c);
extern BrotliDecoderResult BrotliDecoderDecompressStream(BrotliDecoderState state, size_t* avail_in, const uint8_t** next_in, size_t* avail_out, uint8_t** next_out, size_t* total_out);
extern void BrotliDecoderDestroyInstance(BrotliDecoderState state);
extern bool BrotliDecoderIsFinished(BrotliDecoderState state);

static const char base64_table[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

static int base64_decode(const char* in, uint8_t* out) {
    int i, j, v;
    int len = strlen(in);
    int table[256];
    for (i = 0; i < 256; i++) table[i] = -1;
    for (i = 0; i < 64; i++) table[(int)base64_table[i]] = i;
    for (i = 0, j = 0; i < len; i += 4) {
        v = table[(int)in[i]] << 18;
        v += table[(int)in[i+1]] << 12;
        if (in[i+2] != '=') v += table[(int)in[i+2]] << 6;
        if (in[i+3] != '=') v += table[(int)in[i+3]];
        out[j++] = (v >> 16) & 0xFF;
        if (in[i+2] != '=') out[j++] = (v >> 8) & 0xFF;
        if (in[i+3] != '=') out[j++] = v & 0xFF;
    }
    return j;
}

static void print_help() {
    printf("Usage: executable [OPTION]... [FILE]...\n");
    printf("Options:\n");
    printf("  -#                          compression level (0-9)\n");
    printf("  -c, --stdout                write on standard output\n");
    printf("  -d, --decompress            decompress\n");
    printf("  -f, --force                 force output file overwrite\n");
    printf("  -h, --help                  display this help and exit\n");
    printf("  -j, --rm                    remove source file(s)\n");
    printf("  -s, --squash                remove destination file if larger than source\n");
    printf("  -k, --keep                  keep source file(s) (default)\n");
    printf("  -n, --no-copy-stat          do not copy source file(s) attributes\n");
    printf("  -o FILE, --output=FILE      output file (only if 1 input file)\n");
    printf("  -q NUM, --quality=NUM       compression level (0-11)\n");
    printf("  -t, --test                  test compressed file integrity\n");
    printf("  -v, --verbose               verbose mode\n");
    printf("  -w NUM, --lgwin=NUM         set LZ77 window size (0, 10-24)\n");
    printf("                              window size = 2**NUM - 16\n");
    printf("                              0 lets compressor choose the optimal value\n");
    printf("  --large_window=NUM          use incompatible large-window brotli\n");
    printf("                              bitstream with window size (0, 10-30)\n");
    printf("                              WARNING: this format is not compatible\n");
    printf("                              with brotli RFC 7932 and may not be\n");
    printf("                              decodable with regular brotli decoders\n");
    printf("  -C B64, --comment=B64       set comment; argument is base64-decoded first;\n");
    printf("                              (maximal decoded length: 80)\n");
    printf("                              when decoding: check stream comment;\n");
    printf("                              when encoding: embed comment (fingerprint)\n");
    printf("  -D FILE, --dictionary=FILE  use FILE as raw (LZ77) dictionary\n");
    printf("  -K, --concatenated          allows concatenated brotli streams as input\n");
    printf("  -S SUF, --suffix=SUF        output file suffix (default:'.br')\n");
    printf("  -V, --version               display version and exit\n");
    printf("  -Z, --best                  use best compression level (11) (default)\n");
    printf("Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.\n");
    printf("With no FILE, or when FILE is -, read standard input.\n");
    printf("All arguments after '--' are treated as files.\n");
}

int main(int argc, char** argv) {
    bool decompress = false, stdout_mode = false, force = false, rm_source = false, squash = false, copy_stat = true, test_mode = false, verbose = false, concat = false, best = false;
    int quality = 11, lgwin = 0, large_window = 0;
    char *output_path = NULL, *suffix = ".br", *comment = NULL;

    const char* prog = strrchr(argv[0], '/');
    prog = prog ? prog + 1 : argv[0];
    if (strcmp(prog, "unbrotli") == 0) decompress = true;
    else if (strcmp(prog, "brcat") == 0) { decompress = true; stdout_mode = true; concat = true; }

    static struct option long_options[] = {
        {"stdout", no_argument, 0, 'c'}, {"decompress", no_argument, 0, 'd'}, {"force", no_argument, 0, 'f'},
        {"help", no_argument, 0, 'h'}, {"rm", no_argument, 0, 'j'}, {"squash", no_argument, 0, 's'},
        {"keep", no_argument, 0, 'k'}, {"no-copy-stat", no_argument, 0, 'n'}, {"output", required_argument, 0, 'o'},
        {"quality", required_argument, 0, 'q'}, {"test", no_argument, 0, 't'}, {"verbose", no_argument, 0, 'v'},
        {"lgwin", required_argument, 0, 'w'}, {"large_window", required_argument, 0, 'L'}, {"comment", required_argument, 0, 'C'},
        {"dictionary", required_argument, 0, 'D'}, {"concatenated", no_argument, 0, 'K'}, {"suffix", required_argument, 0, 'S'},
        {"version", no_argument, 0, 'V'}, {"best", no_argument, 0, 'Z'}, {0, 0, 0, 0}
    };

    int opt;
    while ((opt = getopt_long(argc, argv, "cdfjhkskno:q:tvw:C:D:KS:VZ0123456789", long_options, NULL)) != -1) {
        if (opt >= '0' && opt <= '9') quality = opt - '0';
        else switch (opt) {
            case 'c': stdout_mode = true; break;
            case 'd': decompress = true; break;
            case 'f': force = true; break;
            case 'h': print_help(); return 0;
            case 'j': rm_source = true; break;
            case 's': squash = true; break;
            case 'k': rm_source = false; break;
            case 'n': copy_stat = false; break;
            case 'o': output_path = optarg; break;
            case 'q': quality = atoi(optarg); break;
            case 't': test_mode = true; break;
            case 'v': verbose = true; break;
            case 'w': lgwin = atoi(optarg); break;
            case 'L': large_window = atoi(optarg); break;
            case 'C': comment = optarg; break;
            case 'K': concat = true; break;
            case 'S': suffix = optarg; break;
            case 'V': printf("brotli 1.2.0\n"); return 0;
            case 'Z': best = true; break;
        }
    }
    if (best) quality = 11;

    int next_file_idx = optind;
    bool any_error = false;
    do {
        const char* in_path = (next_file_idx < argc) ? argv[next_file_idx] : "-";
        FILE* in_f = strcmp(in_path, "-") == 0 ? stdin : fopen(in_path, "rb");
        if (!in_f) { fprintf(stderr, "failed to open input file [%s]: No such file or directory\n", in_path); any_error = true; next_file_idx++; continue; }

        char actual_out_path[1024];
        FILE* out_f = NULL;
        if (stdout_mode || strcmp(in_path, "-") == 0) { out_f = stdout; }
        else if (!test_mode) {
            if (output_path) strcpy(actual_out_path, output_path);
            else if (decompress) {
                size_t path_len = strlen(in_path);
                size_t suff_len = strlen(suffix);
                if (path_len > suff_len && strcmp(in_path + path_len - suff_len, suffix) == 0) {
                    strncpy(actual_out_path, in_path, path_len - suff_len);
                    actual_out_path[path_len - suff_len] = '\0';
                } else { fprintf(stderr, "input file [%s] suffix mismatch\n", in_path); any_error = true; fclose(in_f); next_file_idx++; continue; }
            } else { sprintf(actual_out_path, "%s%s", in_path, suffix); }

            if (!force && access(actual_out_path, F_OK) == 0) { fprintf(stderr, "failed to open output file [%s]: File exists\n", actual_out_path); any_error = true; fclose(in_f); next_file_idx++; continue; }
            out_f = fopen(actual_out_path, "wb");
            if (!out_f) { fprintf(stderr, "failed to open output file [%s]: No such file or directory\n", actual_out_path); any_error = true; fclose(in_f); next_file_idx++; continue; }
        }

        bool success = true;
        if (decompress || test_mode) {
            BrotliDecoderState state = BrotliDecoderCreateInstance(NULL, NULL, NULL);
            uint8_t in_buf[65536], out_buf[65536];
            while (true) {
                size_t avail_in = fread(in_buf, 1, 65536, in_f);
                const uint8_t* next_in = in_buf;
                if (avail_in == 0 && feof(in_f)) break;
                while (avail_in > 0) {
                    size_t avail_out = 65536;
                    uint8_t* next_out = out_buf;
                    BrotliDecoderResult res = BrotliDecoderDecompressStream(state, &avail_in, &next_in, &avail_out, &next_out, NULL);
                    if (out_f && !test_mode) fwrite(out_buf, 1, 65536 - avail_out, out_f);
                    if (res == BROTLI_DECODER_RESULT_ERROR) { fprintf(stderr, "corrupt input [%s]\n", in_path); success = false; break; }
                    if (res == BROTLI_DECODER_RESULT_SUCCESS) {
                        if (concat && avail_in > 0) { BrotliDecoderDestroyInstance(state); state = BrotliDecoderCreateInstance(NULL, NULL, NULL); continue; }
                        if (!concat && avail_in > 0) { fprintf(stderr, "corrupt input [%s]\n", in_path); success = false; }
                        break;
                    }
                }
                if (!success) break;
            }
            BrotliDecoderDestroyInstance(state);
        } else {
            BrotliEncoderState state = BrotliEncoderCreateInstance(NULL, NULL, NULL);
            BrotliEncoderSetParameter(state, BROTLI_PARAM_QUALITY, quality);
            if (lgwin) BrotliEncoderSetParameter(state, BROTLI_PARAM_LGWIN, lgwin);
            if (large_window) { BrotliEncoderSetParameter(state, BROTLI_PARAM_LARGE_WINDOW, 1); BrotliEncoderSetParameter(state, BROTLI_PARAM_LGWIN, large_window); }
            if (comment) {
                uint8_t cm_buf[128];
                int cm_len = base64_decode(comment, cm_buf);
                size_t avail_in = cm_len;
                const uint8_t* next_in = cm_buf;
                size_t avail_out = 0;
                BrotliEncoderCompressStream(state, BROTLI_OPERATION_EMIT_METADATA, &avail_in, &next_in, &avail_out, NULL, NULL);
            }
            uint8_t in_buf[65536], out_buf[65536];
            while (true) {
                size_t avail_in = fread(in_buf, 1, 65536, in_f);
                const uint8_t* next_in = in_buf;
                bool is_eof = feof(in_f);
                while (true) {
                    size_t avail_out = 65536;
                    uint8_t* next_out = out_buf;
                    BrotliEncoderCompressStream(state, is_eof ? BROTLI_OPERATION_FINISH : BROTLI_OPERATION_PROCESS, &avail_in, &next_in, &avail_out, &next_out, NULL);
                    if (out_f) fwrite(out_buf, 1, 65536 - avail_out, out_f);
                    if (is_eof) { if (BrotliEncoderIsFinished(state)) break; } else if (avail_in == 0) break;
                }
                if (is_eof) break;
            }
            BrotliEncoderDestroyInstance(state);
        }
        if (in_f != stdin) fclose(in_f);
        if (out_f && out_f != stdout) fclose(out_f);

        if (success && out_f && out_f != stdout) {
            struct stat st;
            if (stat(in_path, &st) == 0) {
                if (copy_stat) { chmod(actual_out_path, st.st_mode & 07777); struct utimbuf ut; ut.actime = st.st_atime; ut.modtime = st.st_mtime; utime(actual_out_path, &ut); }
                else { chmod(actual_out_path, 0600); }
                if (squash) { struct stat ost; if (stat(actual_out_path, &ost) == 0 && ost.st_size > st.st_size) unlink(actual_out_path); }
            }
            if (rm_source) unlink(in_path);
        } else if (!success) { any_error = true; if (out_f && out_f != stdout) unlink(actual_out_path); }
        next_file_idx++;
    } while (next_file_idx < argc);

    return any_error ? 1 : 0;
}
EOF
./compile.sh
./executable --version
"}
